-- ==============================================================
-- FILE SKEMA RESET DATABASE: Jelajah Wisata Lampung
-- Jalankan seluruh skrip ini di SQL Editor Supabase.
-- Total Destinasi: 156 objek wisata tersebar merata di 15 Kabupaten/Kota
-- ==============================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

DROP TABLE IF EXISTS public.destinations CASCADE;

CREATE TABLE public.destinations (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL,
    regency text NOT NULL,
    category text NOT NULL,
    ticket_price integer NOT NULL DEFAULT 0 CHECK (ticket_price >= 0),
    open_hours text NOT NULL DEFAULT '08.00 - 17.00 WIB',
    facilities text[] NOT NULL DEFAULT '{}',
    description text,
    image_url text,
    maps_url text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_destinations_regency ON public.destinations (regency);
CREATE INDEX idx_destinations_category ON public.destinations (category);
CREATE INDEX idx_destinations_name ON public.destinations (name);

ALTER TABLE public.destinations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public full access destinations" ON public.destinations;
CREATE POLICY "Public full access destinations"
    ON public.destinations
    FOR ALL
    TO anon, authenticated
    USING (true)
    WITH CHECK (true);

